export enum ConfidenceLevel {
  /** 50 or more votes at the target player count */
  High = 'HIGH',
  /** Fewer than 20 votes, or the range-midpoint fallback is in use */
  Low = 'LOW',
  /** 20–49 votes at the target player count */
  Medium = 'MEDIUM'
}

