export type Mutation = {
  __typename?: 'Mutation';
  /** Accept a group invitation using a magic-link token. */
  acceptGroupInvite?: Maybe<AcceptGroupInvitePayload>;
  /** Bind a validated BGG username to the current user. */
  bindBggUsername?: Maybe<BindBggUsernamePayload>;
  /** Cancel an active session. */
  cancelSession?: Maybe<CancelSessionPayload>;
  /** Create a new friend group and become the owner. */
  createGroup?: Maybe<CreateGroupPayload>;
  /** Create a new night session in draft state. */
  createNightSession?: Maybe<CreateNightSessionPayload>;
  /** Enqueue a BGG collection import for a username and return the user with initial sync status. */
  importCollection?: Maybe<ImportCollectionPayload>;
  /** Invite someone to join a group by email. */
  inviteToGroup?: Maybe<InviteToGroupPayload>;
  /** Pick a game from the group's collection and complete the session. */
  pickGame?: Maybe<PickGamePayload>;
  /** Remove a member from a group. */
  removeGroupMember?: Maybe<RemoveGroupMemberPayload>;
  /** Reopen a cancelled session to its previous state. */
  reopenSession?: Maybe<ReopenSessionPayload>;
  /** RSVP to a session via a magic-link invite token. */
  rsvp?: Maybe<RsvpPayload>;
  /** Schedule a draft session and send invitations. */
  scheduleSession?: Maybe<ScheduleSessionPayload>;
  /** Authenticate with email and password and return a bearer token. */
  signIn?: Maybe<SignInPayload>;
  /** Destroy the current session and log out. */
  signOut?: Maybe<SignOutPayload>;
  /** Create a new user account and return a bearer token. */
  signUp?: Maybe<SignUpPayload>;
  /** Transition an invited session to the picking state. */
  startPicking?: Maybe<StartPickingPayload>;
  /** Change a member's role between admin and member. */
  updateGroupMemberRole?: Maybe<UpdateGroupMemberRolePayload>;
  /** Edit a session's time budget and complexity preference before picking starts. */
  updateSessionPreferences?: Maybe<UpdateSessionPreferencesPayload>;
  /** Convert a provisional user to a full account. */
  upgradeToAccount?: Maybe<UpgradeToAccountPayload>;
  /** Validate a BGG username format and existence. */
  validateBggUsername?: Maybe<ValidateBggUsernamePayload>;
};


