export enum SessionState {
  /** Session was cancelled and can be reopened */
  Cancelled = 'CANCELLED',
  /** Game picked and session finalized */
  Completed = 'COMPLETED',
  /** Session is being edited */
  Draft = 'DRAFT',
  /** Invitations sent, RSVPs open */
  Invited = 'INVITED',
  /** Host is picking a game */
  Picking = 'PICKING'
}

